// Die Instanzwerte kommen aus sub-einstellungen (Knoten davor) und werden
// in der Data Table pw_config gepflegt (n8n-Oberfläche, "Data Tables").
// HIER stehen nur die FACHLICHEN Einstellungen dieses Workflows: Fristen,
// Tag-Namen, Feldnamen.
const werte = $('Einstellungen holen').first().json;
const pw = (key) => {
  const v = werte[key];
  if (v === undefined || String(v).trim() === '') {
    throw new Error('pw_config: "' + key + '" fehlt oder ist leer; in der n8n-Oberfläche unter "Data Tables" eintragen.');
  }
  return v;
};
return [{
  json: {
    // ── aus der Data Table pw_config ──
    paperless_url:             pw('paperless_url'),
    paperless_url_oeffentlich: pw('paperless_url_oeffentlich'),
    empfaenger_email:          pw('mail_betrieb'),
    absender:                  pw('mail_absender'),

    // ── fachlich, hier zu pflegen ──
    // tag_angebot:   Der Tag, den ein Mensch beim Verschicken des Angebots setzt.
    // nachfass_tage: Ab wann ein Angebot ohne Rückmeldung gemeldet wird.
    tag_angebot: 'angebot-offen',
    nachfass_tage: 14
  }
}];

// Tag-ID auflösen und den Stichtag berechnen: gemeldet wird alles,
// was älter ist als heute minus nachfass_tage.
const cfg = $('Konfiguration').first().json;
const tags = $json.results || [];

const tag = tags.find(t => String(t.name || '').toLowerCase() === cfg.tag_angebot.toLowerCase());
if (!tag) throw new Error('Tag "' + cfg.tag_angebot + '" existiert nicht in Paperless; bitte anlegen und bei jedem verschickten Angebot setzen.');

const cutoff = new Date(Date.now() - cfg.nachfass_tage * 86400000).toISOString().slice(0, 10);

return [{ json: Object.assign({}, cfg, { tag_angebot_id: tag.id, cutoff }) }];

// HTML-Mail mit allen nachzufassenden Angeboten aufbauen,
// älteste (= am längsten offene) zuerst.
const cfg = $('Tag-ID ermitteln').first().json;
const docs = $('Offene Angebote laden').first().json.results || [];

const korr = {};
($input.first().json.results || []).forEach(k => { korr[k.id] = k.name; });

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const fmt = (iso) => iso ? new Date(iso).toLocaleDateString('de-DE') : '-';
const tageOffen = (iso) => iso ? Math.floor((Date.now() - new Date(iso).getTime()) / 86400000) : null;

const rows = docs.map(d => {
  const docUrl = cfg.paperless_url_oeffentlich + '/documents/' + d.id + '/detail';
  const tage = tageOffen(d.created);
  return '<tr>'
    + '<td style="padding:6px 12px;border:1px solid #ddd;"><a href="' + docUrl + '" style="color:#1a73e8;">' + esc(d.title || '(kein Titel)') + '</a></td>'
    + '<td style="padding:6px 12px;border:1px solid #ddd;">' + esc(d.correspondent ? (korr[d.correspondent] || '-') : '-') + '</td>'
    + '<td style="padding:6px 12px;border:1px solid #ddd;white-space:nowrap;">' + fmt(d.created) + '</td>'
    + '<td style="padding:6px 12px;border:1px solid #ddd;color:#c0392b;font-weight:bold;white-space:nowrap;">' + (tage !== null ? tage + ' Tage' : '-') + '</td>'
    + '</tr>';
}).join('\n');

const anzahl = docs.length + (docs.length === 1 ? ' Angebot' : ' Angebote');
const today = new Date().toLocaleDateString('de-DE', { timeZone: 'Europe/Berlin' });

const html = '<div style="font-family:Arial,sans-serif;max-width:750px;">'
  + '<h2 style="color:#2c3e50;border-bottom:2px solid #2c3e50;padding-bottom:8px;">Angebote nachfassen</h2>'
  + '<p><strong>' + anzahl + '</strong> ohne R\u00fcckmeldung seit \u00fcber ' + cfg.nachfass_tage + ' Tagen \u2014 ein kurzer Anruf lohnt sich:</p>'
  + '<table cellpadding="0" cellspacing="0" style="border-collapse:collapse;font-size:14px;width:100%;margin:16px 0;">'
  + '<thead><tr style="background:#2c3e50;color:#fff;">'
  + '<th style="padding:10px 12px;text-align:left;">Angebot</th>'
  + '<th style="padding:10px 12px;text-align:left;">Kunde</th>'
  + '<th style="padding:10px 12px;text-align:left;">Vom</th>'
  + '<th style="padding:10px 12px;text-align:left;">Offen seit</th>'
  + '</tr></thead>'
  + '<tbody>' + rows + '</tbody></table>'
  + '<p style="font-size:13px;color:#555;">Nach Auftrag oder Absage das Tag \u201e' + esc(cfg.tag_angebot) + '\u201c am Dokument entfernen \u2014 sonst erscheint das Angebot n\u00e4chste Woche wieder.</p>'
  + '<p><a href=' + cfg.paperless_url_oeffentlich + ' style="background:#2c3e50;color:#fff;padding:8px 16px;text-decoration:none;border-radius:4px;display:inline-block;">&#8594; Paperless-NGX \u00f6ffnen</a></p>'
  + '<p style="color:#95a5a6;font-size:12px;margin-top:32px;border-top:1px solid #eee;padding-top:12px;">Automatisch generiert am ' + today + ' \u00b7 <a href="https://github.com/paper-werk">Paper-Werk</a></p>'
  + '</div>';

return [{ json: {
  html,
  toEmail: cfg.empfaenger_email,
  fromEmail: cfg.absender,
  subject: 'Nachfassen: ' + anzahl + ' ohne R\u00fcckmeldung'
} }];
